import flet as ft

def main(page: ft.Page):
    page.title = 'Flet Flutter-Style Dashboard'
    page.vertical_alignment = ft.MainAxisAlignment.CENTER
    page.add(
        ft.Row(
            [
                ft.Text('Modern Responsive Components', size=24),
            ],
            alignment=ft.MainAxisAlignment.CENTER,
        )
    )

if __name__ == '__main__':
    ft.app(target=main)

