import arcade

class Game(arcade.Window):
    def __init__(self):
        super().__init__(800, 600, 'OpenGL Accelerated Arcade App')
    def on_draw(self):
        self.clear()
        arcade.draw_text('Arcade Visualizer', 400, 300, arcade.color.AMAZON, 24, anchor_x='center')

if __name__ == '__main__':
    window = Game()
    arcade.run()

import pyglet

window = pyglet.window.Window(800, 600, 'Pyglet multimedia/OpenGL Window')
label = pyglet.text.Label('Low-Level Media Loop', x=window.width//2, y=window.height//2, anchor_x='center', anchor_y='center')

@window.event
def on_draw():
    window.clear()
    label.draw()

if __name__ == '__main__':
    pyglet.app.run()

